<script lang="ts">
	// @ts-expect-error — generated by Wails
	import { GetLanguages, SetSelectedLanguage } from '@wails/go/main/App.js';
	import Dropdown from '$components/Dropdown.svelte';

	interface Language {
		code: string;
		name: string;
		locale: string;
	}

	let languages = $state<Language[]>([]);
	let selectedCode = $state<string>('');
	let loading = $state(true);

	function toDropdownOption(lang: Language): { value: string; label: string } {
		return { value: lang.code, label: lang.name };
	}

	async function loadLanguages(): Promise<void> {
		try {
			languages = await GetLanguages();
			if (languages.length > 0) {
				selectedCode = languages[0].code;
			}
		} catch (err) {
			console.error('Failed to load languages:', err);
		} finally {
			loading = false;
		}
	}

	async function onLanguageChange(value: string): Promise<void> {
		selectedCode = value;
		try {
			await SetSelectedLanguage(selectedCode);
		} catch (err) {
			console.error('Failed to set language:', err);
		}
	}

	const dropdownOptions = $derived(languages.map(toDropdownOption));

	loadLanguages();
</script>

<div class="page">
	<h2>Welcome Page</h2>
	<p>This is page 1 of 5.</p>

	{#if loading}
		<span class="loading-text">Loading...</span>
	{:else}
		<Dropdown
			options={dropdownOptions}
			selectedValue={selectedCode}
			placeholder="Language"
			onChange={onLanguageChange}
		/>
	{/if}
</div>

